E=[
# ——— أزواجه ———
('A01',A,'أزواجه','زوجته خديجة بنت خويلد، بشّرها ﷺ ببيت في الجنة.','البخاري 3817، ومسلم 2433',SBM,'وأمره ربه عز وجل أو جبريل عليه السلام أن يبشرها ببيت في الجنة من قصب',''),
('A02',A,'أزواجه','زوجته سودة بنت زمعة، وكانت عائشة تتمنّى أن تكون مثلها.','مسلم 1463',SM,'ما رأيت امرأة أحب إلي أن أكون في مسلاخها من سودة بنت زمعة','لخّصتُ قول عائشة بطلبك؛ والمِسلاخ: الجِلد، أي: أن تكون مثلها.'),
('A03',A,'أزواجه','زوجته عائشة بنت أبي بكر، قال ﷺ: «فضلُ عائشة على النساء كفضل الثريد على سائر الطعام».','البخاري 3770، ومسلم 2446',SBM,'فضل عائشة على النساء كفضل الثريد على سائر الطعام','الثريد: خبز مفتوت في مرق، وكان من أفضل طعامهم؛ الشريط لا يتّسع للتفسير. البديل الآخر «أيّ الناس أحبّ إليك؟ قال: عائشة» مكرّر مع X20.'),
('A04',A,'أزواجه','زوجته حفصة بنت عمر بن الخطاب، وعندها حُفظت الصحف التي جُمع فيها القرآن.','البخاري 4986',SB,'فكانت الصحف عند أبي بكر حتى توفاه الله ثم عند عمر حياته ثم عند حفصة بنت عمر',''),
('A05',A,'أزواجه','زوجته زينب بنت خزيمة، كان يقال لها «أم المساكين» لأنها كانت تطعمهم وتتصدّق عليهم.','الإصابة لابن حجر 8/157','من كتب التراجم — ابن حجر في الإصابة','وكانت يقال لها أم المساكين، لأنها كانت تطعمهم وتتصدق عليهم',''),
('A06',A,'أزواجه','زوجته أم سلمة، واسمها هند، وكان أبوها يُلقَّب «زاد الركب»: إذا سافر كفى رفقته الزاد، فلا يحمل أحد منهم زادًا.','الإصابة لابن حجر 8/342','من كتب التراجم — ابن حجر في الإصابة','وكان أبوها يلقب زاد الركب، لأنه كان أحد الأجواد فكان إذا سافر لم يحمل أحد معه من رفقته زادا، بل هو كان يكفيهم','موقفها يوم الحديبية مكرّر مع I08، فاخترتُ اسمها ولقب أبيها.'),
('A07',A,'أزواجه','زوجته زينب بنت جحش، كانت تعمل بيدها وتتصدّق، فقال ﷺ لأزواجه: «أسرعكنّ لحاقًا بي أطولكنّ يدًا»، فكانت هي.','مسلم 2452',SM,'أسرعكن لحاقا بي أطولكن يدا. قالت فكن يتطاولن أيتهن أطول يدا. قالت فكانت أطولنا يدا زينب لأنها كانت تعمل بيدها وتصدق','«أطولكنّ يدًا»: أكثركنّ صدقة، كما في آخر الحديث.'),
('A08',A,'أزواجه','زوجته جويرية بنت الحارث، كان اسمها «بَرّة» فسمّاها ﷺ جويرية.','مسلم 2140',SM,'كانت جويرية اسمها برة فحول رسول الله صلى الله عليه وسلم اسمها جويرية',''),
('A09',A,'أزواجه','زوجته أم حبيبة، واسمها رملة بنت أبي سفيان، سمعته ﷺ يذكر فضل اثنتي عشرة ركعة في اليوم، فقالت: «فما تركتهنّ منذ سمعتهنّ».','مسلم 728، والإصابة 8/140',SM,'من صلى اثنتى عشرة ركعة في يوم وليلة بني له بهن بيت في الجنة. قالت أم حبيبة فما تركتهن منذ سمعتهن','اسمها: «رملة أصحّ، وقيل: هند» (الإصابة).'),
('A10',A,'أزواجه','زوجته صفية بنت حُيي، أعتقها ﷺ وجعل عتقها مهرها.','البخاري 5086، ومسلم 1365',SBM,'أن رسول الله صلى الله عليه وسلم أعتق صفية، وجعل عتقها صداقها','موقفا «إنك لابنة نبي» وإيصالها إلى بيتها مكرّران مع B11 وKB22. هذا الخبر فيه أنها كانت من السبي؛ إن رأيته يحتاج شرحًا نبدّله.'),
('A11',A,'أزواجه','زوجته ميمونة بنت الحارث، خالة ابن عباس، وفي بيتها بات ابن عباس ليلة فرأى قيامه ﷺ في الليل.','البخاري 138، ومسلم 763',SBM,'بت عند خالتي ميمونة ليلة، فقام النبي صلى الله عليه وسلم من الليل',''),
('A12',A,'أم ولده','مارية القبطية، أمّ ابنه إبراهيم، وقدمت عليه من مصر.','الإصابة لابن حجر 1/318 و1/623','من كتب التراجم — ابن حجر في الإصابة','إبراهيم ابن سيد البشر محمد بن عبد الله … أمه مارية القبطية … بعث حاطب بن أبي بلتعة إلى المقوقس … فأهدى إليه جاريتين إحداهما أم إبراهيم','أدخلتُها بطلبك، بلا «زوجته».'),
# ——— أولاده ———
('B01',A,'أولاده','ابنه القاسم، وبه كان يُكنى ﷺ «أبا القاسم».','سيرة ابن هشام، والإصابة 3/445','من كتب السيرة — ابن إسحاق','ولدت خديجة لرسول الله ﷺ ولده كلهم إلا إبراهيم: القاسم، وبه كان يُكنى','قريب من KN16 وKN03، لكنه هنا تعريف بالاسم وحده.'),
('B02',A,'أولاده','ابنه عبد الله، وقيل: «الطيّب» و«الطاهر» لقبان له، ومات صغيرًا بمكة.','الإصابة لابن حجر 3/445 و5/6','من كتب التراجم — ابن حجر في الإصابة، والمسألة مختلف فيها','وجزم هشام بن الكلبي بأن عبد الله والطيب والطاهر واحد اسمه عبد الله، والطيب والطاهر لقبان له … فأما الذكور فماتوا كلهم بمكة','في KN16 (ابن إسحاق) الطاهر والطيب ابنان آخران؛ لذلك كتبتُ «وقيل».'),
('B03',A,'أولاده','ابنته زينب، وزوجها أبو العاص بن الربيع، أثنى عليه ﷺ فقال: «حدّثني فصدقني، ووعدني فوفى لي».','البخاري 3729، ومسلم 2449',SBM,'وذكر صهرا له من بني عبد شمس فأثنى عليه في مصاهرته إياه فأحسن قال حدثني فصدقني، ووعدني فوفى لي','قصة القلادة مكرّرة مع W09. وفي مسلم 2449 تسميته: «أنكحتُ أبا العاص بن الربيع فحدّثني فصدقني».'),
('B04',A,'أولاده','ابنته رقية، زوجة عثمان، مرضت أيام بدر فبقي عثمان يمرّضها، فقال له ﷺ: «إنّ لك أجرَ رجل ممن شهد بدرًا وسهمَه».','البخاري 3130',SB,'وكانت تحته بنت رسول الله صلى الله عليه وسلم وكانت مريضة. فقال له النبي إن لك أجر رجل ممن شهد بدرا وسهمه','قريب من KN17.'),
('B05',A,'أولاده','ابنته أم كلثوم، تزوّجها عثمان بعد أختها رقية، فقيل له: «ذو النورين».','الإصابة لابن حجر 2/349','من كتب التراجم — ابن حجر: «المشهور أن ذلك لكونه تزوّج ببنتي النبي ﷺ»','ذو النورين: عثمان بن عفان، مشهور بها، والمشهور أن ذلك لكونه تزوج ببنتي النبي واحدة بعد أخرى',''),
('B06',A,'أولاده','ابنته فاطمة، قال ﷺ: «فاطمة بَضْعةٌ مني»؛ أي: قطعة مني.','البخاري 3714',SB,'فاطمة بضعة مني، فمن أغضبها أغضبني','قريب من E03؛ وبقية أخبارها مكرّرة كلها (X17 وE02).'),
('B07',A,'أولاده','ابنه إبراهيم، مات صغيرًا، فقال ﷺ: «إنّ له مُرضِعًا في الجنة».','البخاري 1382',SB,'لما توفي إبراهيم عليه السلام قال رسول الله صلى الله عليه وسلم إن له مرضعا في الجنة','دمعه ﷺ عليه وتسميته مكرّران مع W06 وHB18.'),
# ——— أحفاده ———
('B08',A,'أحفاده','حفيده الحسن بن علي، كان أشبه الناس به ﷺ.','البخاري 3752',SB,'لم يكن أحد أشبه بالنبي صلى الله عليه وسلم من الحسن بن علي','«إن ابني هذا سيد» مكرّر مع HB19.'),
('B09',A,'أحفاده','حفيده الحسين بن علي، قال ﷺ: «حسينٌ مني وأنا من حسين».','الترمذي 3775، وابن ماجه 144','حسن — الترمذي، وحسّنه أحمد شاكر والألباني','حسين مني وأنا من حسين أحب الله من أحب حسينا',''),
('B10',A,'أحفاده','حفيدته أمامة بنت زينب، كان ﷺ يحملها وهو يصلّي، فإذا سجد وضعها، وإذا قام حملها.','البخاري 516، ومسلم 543',SBM,'كان يصلي وهو حامل أمامة بنت زينب بنت رسول الله … فإذا سجد وضعها وإذا قام حملها','قريب من P04.'),
# ——— أقاربه ———
('B11',A,'أقاربه','ابن عمّه علي بن أبي طالب، قال له ﷺ: «أما ترضى أن تكون مني بمنزلة هارون من موسى؟»','البخاري 3706، ومسلم 2404',SBM,'أما ترضى أن تكون مني بمنزلة هارون من موسى','«أبو تراب» مكرّر مع B12.'),
('B12',A,'أقاربه','عمّه حمزة بن عبد المطلب، وكان أخاه من الرضاعة أيضًا.','البخاري 5100، ومسلم 1446',SBM,'ألا تزوج ابنة حمزة قال إنها ابنة أخي من الرضاعة','قريب من KN07. لقب «أسد الله» لم أجد له إسنادًا صحيحًا عندي، فتركتُه.'),
('B13',A,'أقاربه','عمّه العباس بن عبد المطلب، قال ﷺ: «أما شعرتَ أنّ عمّ الرجل صِنْوُ أبيه؟»؛ أي: مثل أبيه.','مسلم 983',SM,'يا عمر أما شعرت أن عم الرجل صنو أبيه','الصِّنو: المِثل، وأصله نخلتان تطلعان من أصل واحد (النهاية 3/57).'),
('B14',A,'أقاربه','ابن عمّه جعفر بن أبي طالب، يُلقَّب «ذا الجناحين»، وكان ابن عمر إذا سلّم على ابنه قال: «السلام عليك يا ابن ذي الجناحين».','البخاري 3709',SB,'كان إذا سلم على ابن جعفر قال السلام عليك يا ابن ذي الجناحين','«أشبهتَ خَلقي وخُلقي» مكرّر مع HB22.'),
# الدفعة 3 (أقرّها المستخدم كلها 2026-11-23)
('B15', A, 'أقاربه', 'ابنة عمّه أم هانئ بنت أبي طالب، أجارت رجلًا يوم فتح مكة، فقال ﷺ: «قد أجرنا من أجرتِ يا أم هانئ»؛ أي: أمّنّا من أمّنتِ.', 'البخاري 357، ومسلم 336', 'صحيح — البخاري ومسلم', 'قد أجرنا من أجرت يا أم هانئ', ''),
('B16', A, 'أقاربه', 'عمّته صفية بنت عبد المطلب، أم الزبير، ناداها ﷺ: «يا صفية عمّة رسول الله، لا أُغني عنكِ من الله شيئًا»؛ أي: لا ينفع القُربُ منه بلا عمل.', 'البخاري 2753، ومسلم 206', 'صحيح — البخاري ومسلم', 'يا صفية عمة رسول الله لا أغني عنك من الله شيئا', 'قالها حين نزل ﴿وأنذر عشيرتك الأقربين﴾، ونادى معها العباس وفاطمة.'),
('B17', A, 'أقاربه', 'ابن عمّه أبو سفيان بن الحارث، ثبت معه يوم حُنين حين انكشف الناس، آخذًا بلجام بغلته.', 'البخاري 2874، ومسلم 1776', 'صحيح — البخاري ومسلم', 'وأبو سفيان بن الحارث آخذ بلجامها', 'غير أبي سفيان بن حرب والد معاوية. R01 عن ثباته ﷺ يومها، وهذا عن ابن عمّه.'),
('B18', A, 'أقاربه', 'ابن عمّه الفضل بن العباس، أردفه ﷺ خلفه في الحج، من مزدلفة إلى منى.', 'البخاري 1544، ومسلم 1218', 'صحيح — البخاري ومسلم', 'ثم أردف الفضل من المزدلفة إلى منى', ''),
('B19', A, 'أقاربه', 'أم الفضل، زوجة عمّه العباس، شكّ الناس يوم عرفة: أصائم هو؟ فأرسلت إليه قدح لبن وهو واقف على بعيره، فشربه.', 'البخاري 1661، ومسلم 1123', 'صحيح — البخاري ومسلم', 'فأرسلت إليه بقدح لبن وهو واقف على بعيره فشربه', ''),
('B20', A, 'ربائبه', 'ربيبه عمر بن أبي سلمة، ابن زوجته أم سلمة، نشأ صغيرًا في حِجره ﷺ، وفي بيته تعلّم آداب الطعام.', 'البخاري 5376، ومسلم 2022', 'صحيح — البخاري ومسلم', 'كنت غلاما في حجر رسول الله صلى الله عليه وسلم', 'الربيب: ابن الزوجة من غيره. «يا غلام سمِّ الله» في بطاقة C26 فلم أكرّرها.'),
('B21', A, 'ربائبه', 'ربيبته زينب بنت أبي سلمة، كان اسمها «بَرّة» فسمّاها ﷺ زينب، وقال: «لا تُزكّوا أنفسكم».', 'مسلم 2142', 'صحيح — مسلم', 'كان اسمي برة فسماني رسول الله صلى الله عليه وسلم زينب … لا تزكوا أنفسكم', 'بَرّة: من البِرّ، فكره ﷺ أن يمدح الإنسان نفسه باسمه.'),
# ——— أصحابه ———
('S01',S,'أصحابه','أبو بكر الصديق، اسمه عبد الله بن عثمان، وأبو قحافة كنية أبيه؛ قال ﷺ: «لو كنتُ متخذًا خليلًا لاتخذتُ أبا بكر خليلًا».','مسلم 2383، والإصابة 4/144',SM,'لو كنت متخذا خليلا لاتخذت أبا بكر خليلا','الإصابة: «عبد الله بن عثمان بن عامر … أبو بكر الصديق بن أبي قحافة».'),
('S02',S,'أصحابه','عمر بن الخطاب، قال ﷺ: «لقد كان فيما قبلكم من الأمم محدَّثون، فإن يكُ في أمتي أحد فإنه عمر»؛ والمحدَّث: المُلهَم.','البخاري 3689',SB,'لقد كان فيما قبلكم من الأمم محدثون، فإن يك في أمتي أحد فإنه عمر','«المحدَّث: المُلهَم، قاله الأكثر» (فتح الباري 7/50). «ما لقيك الشيطان سالكًا فجًّا» مكرّر مع D19.'),
('S03',S,'أصحابه','عثمان بن عفان، قال ﷺ: «ألا أستحيي من رجل تستحيي منه الملائكة؟»','مسلم 2401',SM,'ألا أستحي من رجل تستحي منه الملائكة',''),
('S04',S,'أصحابه','أبو هريرة، اسمه على الأشهر عبد الرحمن بن صخر الدوسي، وكُنّي بهرّة صغيرة كان يلعب بها وهو يرعى غنم أهله.','الترمذي 3840، والإصابة 4/267','حسن — الترمذي، وحسّن إسناده أحمد شاكر والألباني','كنت أرعى غنم أهلي فكانت لي هريرة صغيرة فكنت أضعها بالليل في شجرة فإذا كان النهار ذهبت بها معي فلعبت بها فكنوني أبا هريرة','اسمه مختلف فيه كثيرًا؛ ابن حجر: «هذا أشهر ما قيل في اسمه واسم أبيه».'),
('S05',S,'أصحابه','أنس بن مالك، خدمه ﷺ عشر سنين، ودعا له: «اللهم أكثِر ماله وولده، وبارك له فيما أعطيته».','البخاري 6334، ومسلم 2309',SBM,'اللهم أكثر ماله وولده، وبارك له فيما أعطيته','قريب من C40 (الدعاء) وP01 (الخدمة).'),
('S06',S,'أصحابه','زيد بن حارثة، قال عنه ﷺ: «وايمُ الله إن كان لخليقًا للإمارة، وإن كان لمن أحبّ الناس إليّ».','البخاري 3730',SB,'وايم الله، إن كان لخليقا للإمارة، وإن كان لمن أحب الناس إلي','«خليقًا»: جديرًا. «أنت أخونا ومولانا» مكرّر مع HB22.'),
('S07',S,'أصحابه','أسامة بن زيد، كان الصحابة يسمّونه «حِبّ رسول الله ﷺ»؛ أي: محبوبه.','البخاري 6788، ومسلم 1688',SBM,'ومن يجترئ عليه إلا أسامة حب رسول الله',''),
('S08',S,'أصحابه','بلال بن رباح، قال له ﷺ: «سمعتُ دَفَّ نعليك بين يديّ في الجنة»؛ أي: صوت مشيك.','البخاري 1149',SB,'فإني سمعت دف نعليك بين يدي في الجنة',''),
('S09',S,'أصحابه','عبد الله بن مسعود، قال ﷺ: «استقرئوا القرآن من أربعة»، وبدأ به.','البخاري 3760، ومسلم 2464',SBM,'استقرئوا القرآن من أربعة من عبد الله بن مسعود، وسالم مولى أبي حذيفة، وأبي بن كعب، ومعاذ بن جبل',''),
('S10',S,'أصحابه','أبو عبيدة بن الجراح، قال ﷺ: «لكلّ أمة أمين، وأمينُ هذه الأمة أبو عبيدة».','البخاري 4382، ومسلم 2419',SBM,'لكل أمة أمين، وأمين هذه الأمة أبو عبيدة بن الجراح',''),
('S11',S,'أصحابه','سعد بن أبي وقاص، من أوائل من أسلم، وكان يقول: «وإنّي لثُلُث الإسلام»؛ أي: ثالث من أسلم فيما علم.','البخاري 3727',SB,'ما أسلم أحد إلا في اليوم الذي أسلمت فيه، ولقد مكثت سبعة أيام وإني لثلث الإسلام','ابن حجر: «قال ذلك بحسب اطلاعه» (فتح الباري 7/84). «ارمِ فداك أبي وأمي» مكرّر مع KA24.'),
('S12',S,'أصحابه','معاذ بن جبل، قال ﷺ: «وأعلمُهم بالحلال والحرام معاذ بن جبل».','الترمذي 3790','صحيح — الترمذي، وصحّحه أحمد شاكر والألباني','وأعلمهم بالحلال والحرام معاذ بن جبل','«والله إني لأحبك» مكرّر مع F01.'),
('S13',S,'أصحابه','أُبيّ بن كعب، قال له ﷺ: «إن الله أمرني أن أقرأ عليك القرآن»، فقال: آللهُ سمّاني لك؟ قال: «الله سمّاك لي»، فجعل يبكي.','البخاري 4960، ومسلم 799',SBM,'إن الله أمرني أن أقرأ عليك القرآن. قال أبي آلله سماني لك قال الله سماك لي. فجعل أبي يبكي',''),
('S14',S,'أصحابه','حذيفة بن اليمان، كان يُعرف بأنه «صاحب السرّ» الذي لا يعلمه غيره.','البخاري 3743',SB,'أليس فيكم صاحب السر الذي لا يعلمه غيره يعني حذيفة',''),
('S15',S,'أصحابه','أم أيمن، واسمها بركة، حاضنته ﷺ في صغره، وكان أبو بكر وعمر يزورانها بعده كما كان ﷺ يزورها.','مسلم 2454، والإصابة 8/358',SM,'انطلق بنا إلى أم أيمن نزورها كما كان رسول الله صلى الله عليه وسلم يزورها','قريب من KA06 (بكاؤها). طلحة والزبير تركتُهما الآن: أخبارهما الصحيحة مكرّرة (KB09 وF02)، وحديث «شهيد يمشي» فيه كلام.'),
('S16',S,'أصحابه','طلحة بن عبيد الله، وقى النبي ﷺ بيده يوم أحد حتى شُلّت.','البخاري 4063',SB,'رأيت يد طلحة شلاء، وقى بها النبي صلى الله عليه وسلم يوم أحد','قريب من KB09، وأدخلتُه بطلبك.'),
('S17',S,'أصحابه','الزبير بن العوام، ابن عمّته صفية، جمع له ﷺ أبويه فقال: «فداك أبي وأمي».','البخاري 3720، والإصابة 4/81',SB,'فلما رجعت جمع لي رسول الله صلى الله عليه وسلم أبويه فقال فداك أبي وأمي','يوم الأحزاب، حين أتاه بخبر بني قريظة.'),
# ——— الدفعة 2 (أقرّها المستخدم 2026-11-21، وعدّل S21 وS28) ———
('S18',S,'أصحابه','عبد الرحمن بن عوف، عرض عليه أخوه الأنصاري نصف ماله، فقال: «بارك الله لك في أهلك ومالك، دلّوني على السوق».','البخاري 2049','صحيح — البخاري','قال بارك الله لك في أهلك ومالك، دلوني على السوق',''),
('S19',S,'أصحابه','سعيد بن زيد، أحد العشرة الذين بشّرهم ﷺ بالجنة.','الترمذي 3757','صحيح — قال الترمذي: حسن صحيح','قيل فمن العاشر قال أنا','رقم الحديث في نسخة fawazahmed0، ويُراجَع في sunnah.com قبل النشر (قد يكون 3748).'),
('S20',S,'أصحابه','أبو ذر الغفاري، قال ﷺ: «ما أظلّت الخضراء ولا أقلّت الغبراء من ذي لهجة أصدق ولا أوفى من أبي ذر»؛ أي: ما على الأرض أصدق لسانًا منه.','الترمذي 3802','حسن — الترمذي','ما أظلت الخضراء ولا أقلت الغبراء من ذي لهجة أصدق ولا أوفى من أبي ذر','قال الترمذي: حسن غريب؛ لم أراجع حكم غيره بعد.'),
('S21',S,'أصحابه','سلمان الفارسي، من رامَهُرمُز ببلاد فارس، خرج يطلب الدين الحق، فتنقّل بين أكثر من عشرة أسياد حتى بلغ النبي ﷺ.','البخاري 3946 و3947، وفتح الباري 7/277','صحيح — البخاري','أنه تداوله بضعة عشر من رب إلى رب … أنا من رام هرمز','قال ابن حجر: «أي من سيد إلى سيد»، وذكر أنه خرج في طلب الدين؛ أي: بيع عبدًا وانتقل من سيّد إلى سيّد. بدّلتُ حديث الثريا بطلبك.'),
('S22',S,'أصحابه','خالد بن الوليد، أخذ الراية يوم مؤتة ففتح الله على يديه، فسمّاه ﷺ «سيفًا من سيوف الله».','البخاري 4262، وفتح الباري 7/513','صحيح — البخاري','حتى أخذ الراية سيف من سيوف الله حتى فتح الله عليهم','الاسم ليس في لفظ البخاري؛ قال ابن حجر: «فإن المراد به خالد ومن يومئذ تسمّى سيف الله».'),
('S23',S,'أصحابه','عبد الله بن عباس، ضمّه ﷺ إليه وقال: «اللهم علّمه الكتاب».','البخاري 75','صحيح — البخاري','ضمني رسول الله صلى الله عليه وسلم وقال اللهم علمه الكتاب',''),
('S24',S,'أصحابه','سعد بن معاذ، قال ﷺ حين مات: «اهتزّ العرش لموت سعد بن معاذ».','البخاري 3803، ومسلم 2466','صحيح — البخاري ومسلم','اهتز العرش لموت سعد بن معاذ',''),
('S25',S,'أصحابه','مصعب بن عمير، قُتل يوم أحد ولم يترك إلا ثوبًا، إذا غُطّي به رأسه بدت رجلاه.','البخاري 1276، ومسلم 940','صحيح — البخاري ومسلم','منهم مصعب بن عمير قتل يوم أحد فلم يوجد له شيء يكفن فيه إلا نمرة فكنا إذا وضعناها على رأسه خرجت رجلاه',''),
('S26',S,'أصحابه','أبو موسى الأشعري، قال له ﷺ: «لقد أوتيتَ مزمارًا من مزامير آل داود»؛ أي: صوتًا حسنًا بالقرآن.','البخاري 5048، ومسلم 793','صحيح — البخاري ومسلم','يا أبا موسى لقد أوتيت مزمارا من مزامير آل داود',''),
('S27',S,'أصحابه','عبد الله بن سلام، كان من علماء اليهود، فسأله ﷺ عن ثلاث «لا يعلمهنّ إلا نبي»، فلما أجابه أسلم.','البخاري 3329','صحيح — البخاري','إني سائلك عن ثلاث لا يعلمهن إلا نبي','KA02 عن وجهه ﷺ «ليس بوجه كذّاب»، وهذا خبر آخر.'),
('S28',S,'أصحابه','ثابت بن قيس، كان عالي الصوت، فلما نزل النهي عن رفع الصوت فوق صوت النبي ﷺ ظنّ أن عمله ضاع، فبشّره ﷺ: «إنك لستَ من أهل النار، ولكن من أهل الجنة».','البخاري 3613','صحيح — البخاري','كان يرفع صوته فوق صوت النبي صلى الله عليه وسلم فقد حبط عمله … فقل له إنك لست من أهل النار ولكن من أهل الجنة','أوضحتُ القصة بطلبك، وغيّرتُ المصدر إلى لفظ البخاري.'),
('S29',S,'أصحابه','عُكّاشة بن محصن، سأله أن يدعو له ليكون من السبعين ألفًا الذين يدخلون الجنة بلا حساب، فقال ﷺ: «اللهم اجعله منهم».','البخاري 6541، ومسلم 216','صحيح — البخاري ومسلم','فقام إليه عكاشة بن محصن فقال ادع الله أن يجعلني منهم قال اللهم اجعله منهم',''),
('S30',S,'أصحابه','أسماء بنت أبي بكر، «ذات النطاقين»: شقّت نطاقها نصفين، ربطت بهما طعام النبي ﷺ وسقاءه ليلة الهجرة.','البخاري 2979','صحيح — البخاري','فشقيه باثنين، فاربطيه بواحد السقاء وبالآخر السفرة، ففعلت، فلذلك سميت ذات النطاقين','النطاق: حزام تشدّه المرأة على وسطها. HB39 عنها خبر آخر (صلة أمها).'),
('S31',S,'أصحابه','أبو قتادة وسلمة بن الأكوع، قال ﷺ: «كان خير فرساننا اليوم أبو قتادة، وخير رجّالتنا سلمة»؛ أي: خير المشاة.','مسلم 1807','صحيح — مسلم','كان خير فرساننا اليوم أبو قتادة وخير رجالتنا سلمة',''),
('S32',S,'أصحابه','حسان بن ثابت، قال له ﷺ: «إنّ روح القدس لا يزال يؤيّدك ما نافحتَ عن الله ورسوله»؛ أي: ما دافعت.','مسلم 2490','صحيح — مسلم','إن روح القدس لا يزال يؤيدك ما نافحت عن الله ورسوله','روح القدس: جبريل عليه السلام. أبيات حسان QA18 وQA20 في «قالوا عنه».'),
('S33',S,'أصحابه','البراء بن مالك، قال ﷺ: «كم من أشعث أغبر لا يُؤبه له، لو أقسم على الله لأبرّه، منهم البراء بن مالك».','الترمذي 3854','حسن — الترمذي','كم من أشعث أغبر ذي طمرين لا يؤبه له لو أقسم على الله لأبره منهم البراء بن مالك','قال الترمذي: حسن غريب؛ حُذفت «ذي طمرين» (ثوبين باليين) للاختصار، وأُضيف «…» إن أردت.'),
('S34',S,'أصحابه','عمار بن ياسر، أجاره الله من الشيطان على لسان نبيه ﷺ.','البخاري 3287','صحيح — البخاري','أفيكم الذي أجاره الله من الشيطان على لسان نبيه … يعني عمارا','من قول أبي الدرداء، والتفسير «يعني عمارًا» في رواية البخاري نفسها.'),
# الدفعة 3 (أقرّها المستخدم كلها 2026-11-23)
('S35', S, 'أصحابه', 'أُسيد بن حُضير، قرأ القرآن ليلًا فرأى فوقه مثل الظُّلّة فيها أمثال المصابيح، فقال ﷺ: «تلك الملائكة دنت لصوتك».', 'البخاري 5018، ومسلم 796', 'صحيح — البخاري ومسلم', 'تلك الملائكة دنت لصوتك', 'الظُّلّة: مثل السحابة.'),
('S36', S, 'أصحابه', 'عبد الله بن زيد، رأى الأذان في منامه، فقال ﷺ: «إنها لرؤيا حقّ»، وأمره أن يعلّمه بلالًا لأنه أندى صوتًا.', 'أبو داود 499، والترمذي 189', 'حسن صحيح — الترمذي', 'إنها لرؤيا حق إن شاء الله فقم مع بلال فألق عليه ما رأيت فليؤذن به فإنه أندى صوتا منك', ''),
('S37', S, 'أصحابه', 'عبد الله بن عمرو، كان يكتب كل ما يسمعه منه ﷺ، فقال له: «اكتب، فوالذي نفسي بيده ما يخرج منه إلا حق»، وأشار إلى فمه.', 'أبو داود 3646', 'صحيح — الألباني والأرناؤوط وأحمد شاكر', 'اكتب فوالذي نفسي بيده ما يخرج منه إلا حق', ''),
('S38', S, 'أصحابه', 'جُليبيب، قُتل في غزوة بعد أن قَتل سبعة، فوقف عليه ﷺ وقال: «هذا مني وأنا منه»، وحمله على ساعديه حتى وُضع في قبره.', 'مسلم 2472', 'صحيح — مسلم', 'قتل سبعة ثم قتلوه هذا مني وأنا منه … فوضعه على ساعديه', 'في مسلم: «ليس له إلا ساعدا النبي ﷺ» حتى وُضع في قبره.'),
('S39', S, 'أصحابه', 'أبو دُجانة، رفع ﷺ سيفًا يوم أحد وقال: «من يأخذه بحقّه؟» فأخذه أبو دجانة وقاتل به.', 'مسلم 2470', 'صحيح — مسلم', 'من يأخذ مني هذا … فمن يأخذه بحقه … قال أبو دجانة أنا آخذه بحقه', ''),
]
out=[dict(id=i,head=h,cat=c,text=t,source=s,grade=g,origin=o,note=nt) for i,h,c,t,s,g,o,nt in E]
for x in out: assert len(x['text'])<=150, (x['id'],len(x['text']))
json.dump({'version':2,'lines':out},open('data/ahl/batch1.json','w'),ensure_ascii=False,indent=1)
print(len(out),'ahl',sum(x['head']==A for x in out),'sahb',sum(x['head']==S for x in out), 'max',max(len(x['text']) for x in out))
